const uid = game.user.id;
const book = game.cards.find(c => c.ownership[uid] === 3 && c.system?.fq?.type === "SPELLBOOK" && c.system?.fq?.owner === uid);
const names = [...new Set([...(book?.cards ?? [])].filter(c => c.system?.fq?.class === "trapper" && (c.system?.fq?.choices ?? []).some(x => x.reactive)).map(c => c.name))];
cardContent.chooseCardsList = names.map(n => `fq-card-engine.decks-pattern-fq8.Trapper Base.${n}`).join(",");

const uid = game.user.id;
const book = game.cards.find(c => c.ownership[uid] === 3 && c.system?.fq?.type === "SPELLBOOK" && c.system?.fq?.owner === uid);
const names = [...new Set([...(book?.cards ?? [])].filter(c => c.system?.fq?.class === "trapper" && (c.system?.fq?.choices ?? []).some(x => (x.minions ?? []).some(m => m.type === "beast"))).map(c => c.name))];
cardContent.chooseCardsList = names.map(n => `fq-card-engine.decks-pattern-fq8.Trapper Base.${n}`).join(",");

const beast = FqCardEngineModule.cond.minionTokensOnScene("beast")[0]?.actor;
if (beast) {
const hp = Number(beast.system.attributes.hp.value) || 0;
const bonus = Number(beast.system.fq?.bonus?.damage) || 0;
beast.update({"system.attributes.hp.value": Math.max(1, hp - 10), "system.fq.bonus.damage": Math.max(0, bonus - 2)});
}
